 g=json.loads(json.dumps(template));g['4']['inputs']['image']=files['idle'];g['5']['inputs']['image']=files['hurt'];g['6']['inputs']['image']=files['idle'];g['7']['inputs']['prompt']=prompt;g['7']['inputs']['first_frame']=['4',0];g['7']['inputs']['last_frame']=['4',0]
